// Crew emergency alarm, on every signed-in page (imported by shell.js).
//
// Every 5 s the page asks /api/emergencies. When a crewmate is in danger, a red window opens, a
// siren plays and a voice says "<name>: <problem>" (e.g. "Lara: low blood oxygen") — repeated
// until this member answers "On my way" or "Seen". Everyone sees who is coming.
// Sound and voice are generated by the browser (Web Audio + speech synthesis): no files, no
// internet needed. Browsers only allow sound after the person has touched the page once, so the
// window offers a "turn on the alarm sound" button until then.
import { api, t, escapeHtml, timeAgo, appUrl } from './api.js';

const POLL_MS = 5000;
const RING_EVERY_MS = 9000;
const isAdmin = document.body.dataset.role === 'mission_admin';

let audio = null;
let soundOn = false;
let state = { crew: [], mine: [] };
let lastRing = 0;
const pending = new Set();     // emergencies with an answer being sent

// ---------- Sound ----------

function unlockSound() {
    try {
        audio ??= new AudioContext();
        audio.resume();
        // An empty utterance inside a user gesture unlocks speech for later.
        if ('speechSynthesis' in window) window.speechSynthesis.speak(new SpeechSynthesisUtterance(''));
        soundOn = true;
    } catch (error) { /* no audio on this device: the window still shows */ }
    render();
}
['pointerdown', 'keydown'].forEach((type) => document.addEventListener(type, unlockSound, { once: true, capture: true }));

// Two-tone siren, ~1.6 s.
function siren() {
    if (!audio || audio.state !== 'running') return;
    const start = audio.currentTime;
    const tone = audio.createOscillator();
    const gain = audio.createGain();
    tone.type = 'square';
    for (let i = 0; i < 4; i++) tone.frequency.setValueAtTime(i % 2 ? 660 : 960, start + i * 0.4);
    gain.gain.setValueAtTime(0.0001, start);
    gain.gain.exponentialRampToValueAtTime(0.12, start + 0.05);
    gain.gain.setValueAtTime(0.12, start + 1.5);
    gain.gain.exponentialRampToValueAtTime(0.0001, start + 1.6);
    tone.connect(gain).connect(audio.destination);
    tone.start(start);
    tone.stop(start + 1.65);
}

// Best voice for a language: one installed on this device first (works without internet), then an
// online one (Jordanian Arabic preferred for Arabic), then any voice of that language.
function pickVoice(voices, lang, { localOnly = false } = {}) {
    const ofLang = voices.filter((v) => v.lang.toLowerCase().startsWith(lang) && (!localOnly || v.localService));
    return ofLang.find((v) => v.localService)
        ?? ofLang.find((v) => v.lang.toLowerCase() === 'ar-jo')
        ?? ofLang[0]
        ?? null;
}

// Says each emergency in the interface language. If that voice is missing — or it is an online voice
// and there is no link — it says the English sentence with a voice installed on the device.
function speak(emergencies) {
    if (!('speechSynthesis' in window) || !emergencies.length) return;
    const synth = window.speechSynthesis;
    const lang = document.documentElement.lang || 'en';
    const voices = synth.getVoices();
    const englishLocal = pickVoice(voices, 'en', { localOnly: true }) ?? pickVoice(voices, 'en');
    const voice = pickVoice(voices, lang);

    const say = (text, chosen, fallback) => {
        const utterance = new SpeechSynthesisUtterance(text);
        if (chosen) utterance.voice = chosen;
        utterance.lang = chosen?.lang ?? (lang === 'ar' ? 'ar-JO' : 'en-US');
        utterance.rate = 0.95;
        if (fallback) utterance.onerror = fallback;
        synth.speak(utterance);
    };

    synth.cancel();
    emergencies.forEach((emergency) => {
        if (!voice || (lang !== 'en' && !voice.localService && !navigator.onLine)) {
            say(emergency.speech_en, englishLocal);
            return;
        }
        // An online voice can still fail (link lost): then repeat in English on the device.
        say(emergency.speech, voice, voice.localService ? null : () => say(emergency.speech_en, englishLocal));
    });
}

function ringing() {
    return state.crew.filter((e) => !e.my_response && !e.resolved);
}

// One card and one spoken line per person, even with several problems ("chest pain, can't breathe").
function byAstronaut(emergencies) {
    const groups = new Map();
    emergencies.forEach((e) => {
        const group = groups.get(e.astronaut.id) ?? { astronaut: e.astronaut, items: [] };
        group.items.push(e);
        groups.set(e.astronaut.id, group);
    });
    return [...groups.values()].map((group) => {
        const problems = [...new Set(group.items.map((e) => e.problem))];
        return {
            ...group,
            ids: group.items.map((e) => e.id),
            problem: problems.join(t('common.list_separator')),
            speech: t('emergency.speech', { name: group.astronaut.name, problem: problems.join(t('common.list_separator')) }),
            speech_en: group.items.map((e) => e.speech_en).join(' '),
            kinds: [...new Set(group.items.map((e) => e.kind))],
            created_at: group.items.map((e) => e.created_at).sort()[0],
            responses: group.items.flatMap((e) => e.responses)
                .filter((r, index, all) => all.findIndex((other) => other.name === r.name) === index),
        };
    });
}

function ring() {
    const active = ringing();
    if (!active.length || !soundOn || Date.now() - lastRing < RING_EVERY_MS) return;
    lastRing = Date.now();
    siren();
    setTimeout(() => speak(byAstronaut(active)), 1700);
}

// ---------- Window ----------

const overlay = document.createElement('div');
overlay.className = 'emergency-overlay';
overlay.hidden = true;
overlay.setAttribute('role', 'alertdialog');
overlay.setAttribute('aria-modal', 'true');
overlay.setAttribute('aria-labelledby', 'emergency-title');
document.body.append(overlay);

const toast = document.createElement('div');
toast.className = 'emergency-toast';
toast.hidden = true;
toast.setAttribute('role', 'status');
document.body.append(toast);

function responders(emergency) {
    if (!emergency.responses.length) return `<p class="emergency-responders">${escapeHtml(t('emergency.no_response_yet'))}</p>`;
    return `<ul class="emergency-responders">${emergency.responses.map((r) => `<li>${escapeHtml(t(`emergency.response.${r.response}`, { name: r.name }))}</li>`).join('')}</ul>`;
}

function render() {
    const active = ringing();
    const wasHidden = overlay.hidden;
    overlay.hidden = !active.length;
    if (active.length) {
        overlay.innerHTML = `<div class="emergency-card">
            <p class="emergency-eyebrow"><span class="emergency-pulse" aria-hidden="true"></span>${escapeHtml(t('emergency.title'))}</p>
            <h2 id="emergency-title" class="visually-hidden">${escapeHtml(t('emergency.title'))}</h2>
            ${byAstronaut(active).map((e) => `
                <article class="emergency-item" data-emergency="${e.ids.join(',')}">
                    <p class="emergency-name">${escapeHtml(e.astronaut.name)}</p>
                    <p class="emergency-problem">${escapeHtml(e.problem)}</p>
                    <p class="emergency-meta">${e.kinds.map((kind) => escapeHtml(t(kind === 'vital' ? 'emergency.kind.vital' : 'emergency.kind.symptom'))).join(' · ')} · ${escapeHtml(timeAgo(e.created_at))}</p>
                    ${responders(e)}
                    <div class="emergency-actions">
                        <button class="btn emergency-btn-go" type="button" data-respond="on_my_way" ${e.ids.some((id) => pending.has(id)) ? 'disabled' : ''}>${escapeHtml(t('emergency.on_my_way'))}</button>
                        <button class="btn emergency-btn-seen" type="button" data-respond="seen" ${e.ids.some((id) => pending.has(id)) ? 'disabled' : ''}>${escapeHtml(t('emergency.seen'))}</button>
                        <a class="emergency-link" href="${appUrl(isAdmin ? `pages/crew.php?id=${e.astronaut.id}` : 'pages/mission.php')}">${escapeHtml(t('emergency.open'))}</a>
                    </div>
                </article>`).join('')}
            ${soundOn ? '' : `<button class="emergency-sound" type="button" data-sound>${escapeHtml(t('emergency.turn_on_sound'))}</button>`}
            <p class="emergency-note">${escapeHtml(t('emergency.privacy_note'))}</p>
        </div>`;
        if (wasHidden) overlay.querySelector('[data-respond]')?.focus();
    }

    // The astronaut in danger sees that the crew was alerted, and who is coming.
    const mine = state.mine.filter((e) => !e.resolved);
    toast.hidden = !mine.length;
    if (mine.length) {
        const latest = mine[0];
        const coming = latest.responses.filter((r) => r.response === 'on_my_way').map((r) => r.name);
        toast.innerHTML = `<strong>${escapeHtml(t('emergency.crew_alerted'))}</strong>
            <span>${escapeHtml(coming.length ? t('emergency.coming', { names: coming.join(t('common.list_separator')) }) : t('emergency.waiting'))}</span>`;
    }
}

overlay.addEventListener('click', async (event) => {
    if (event.target.closest('[data-sound]')) {
        unlockSound();
        lastRing = 0;
        ring();
        return;
    }
    const button = event.target.closest('[data-respond]');
    if (!button) return;
    // One answer covers every problem of that person.
    const ids = button.closest('[data-emergency]').dataset.emergency.split(',').map(Number);
    ids.forEach((id) => pending.add(id));
    render();
    try {
        for (const id of ids) {
            state = await api.post(`emergencies/${id}/respond`, { response: button.dataset.respond });
        }
        if (!ringing().length) window.speechSynthesis?.cancel();
    } catch (error) { /* stays ringing; the next poll retries */ }
    ids.forEach((id) => pending.delete(id));
    render();
});

// ---------- Polling (also in background tabs: an emergency must not wait) ----------

async function poll() {
    try {
        state = await api.get('emergencies');
        render();
        ring();
    } catch (error) { /* offline or signed out: try again */ }
    setTimeout(poll, POLL_MS);
}
if ('speechSynthesis' in window) window.speechSynthesis.getVoices();   // starts loading voices early
poll();
